) AS (
  VALUES 
    (317::BIGINT, 'Si quiere que lo menosprecien, adelante. Si quiere que no respeten su tiempo, adelante. Si quiere tener ganas de vomitar cada que habla con el profesor, adelante. Si quiere sentirse miserable, adelante. Si ya sabe de bases de datos y no tiene que aprender, adelante. De otro modo, no lleve con él.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2026-06-30T00:00:00+00:00'::TIMESTAMPTZ, '46dad8f23085e08f66557d2eb59ff0d0333c0df3672e292321d32bcec9b7e11a'::TEXT, ARRAY[1037]::BIGINT[]),
    (317::BIGINT, 'Tuve 3 casos como proyecto, el último valía 45%. A la primera revisión no se presentó, a la segunda llegó tarde. La materia es confusa, no sabe explicar y es arrogante; nos dijo que hacíamos el ridículo. Los proyectos no tienen nada que ver con lo enseñado. No lo matriculen, mejor con Dieguito.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('45','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2026-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'da59200740c606f9c26ba75014352f1d65eb3ca448845beec7feffa0246f4de4'::TEXT, ARRAY[1037]::BIGINT[]),
    (317::BIGINT, 'Clases super confusas, usted no va a aprender nada, no se pone serio al momento de las revisiones porque cambia fechas a cada rato, deja proyectos largos como si fuera el único curso que uno lleva, a veces llega a clases oliendo a alcohol, habla con pereza y se le acerca a LOS estudiantes'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('25','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2025-12-14T00:00:00+00:00'::TIMESTAMPTZ, '2cfaa01daed55c0a270b6b31ee9144cde5ef30e3bd1617bedca17b03e383bf65'::TEXT, ARRAY[1037]::BIGINT[]),
    (317::BIGINT, 'El mae puede ser muy pura vida y todo, pero tiene que ganarse al profe, si no, por más que le pregunte y le mande sus dudas, siempre le va a encontrar algo para bajarle la calificación'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2025-11-18T00:00:00+00:00'::TIMESTAMPTZ, '3ae1395c3382cb9c9c8379e93f02f6fb134745cc04cffbbc7c7c1363bba2cbe3'::TEXT, ARRAY[1047]::BIGINT[]),
    (317::BIGINT, 'Es un raraso, intenta acercarse a los estudiantes de maneras cuestionables, tras de eso las instrucciones de los trabajos son ambiguas, largas y confusas. Califica si le gusta algo bien, si no le gusta a pesar de ser funcional mal. Evite a toda costa matricular con el'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2025-08-05T00:00:00+00:00'::TIMESTAMPTZ, '4932c4d4d84d76bb1502447b60dcd07dd4db036c73018031c92ee31ca1b51f99'::TEXT, ARRAY[1037]::BIGINT[]),
    (317::BIGINT, 'No matricule con este mae si tiene amor propio, no va a aprender, es un desmadre y constantemente lo va a hacer sentir miserable e inutil, no tiene indicaciones claras y es una pérdida de tiempo'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('10','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-07-14T00:00:00+00:00'::TIMESTAMPTZ, '7847aa367d1828a9a55ced2e7223eb4237e7dfbaf603f8a2f0a0c026434a411c'::TEXT, ARRAY[1037]::BIGINT[]),
    (317::BIGINT, 'Las revisiones que hace el profe son muy duras. Si algo no está exactamente como lo quiere, pone un 0 en todo el rubro. No pasa las rúbricas con tiempo, entonces puede calificar muy duro algo que uno consideraba poco relevante. Los enunciados son bastante ambiguos y se enoja si uno los malinterpreta'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'daa1d548f7033f61c6a79a0741c8bde14d67eac2df4f17d9d155e3da17d97247'::TEXT, ARRAY[1043]::BIGINT[]),
    (317::BIGINT, 'La orientación a Data Science que le da al curso es muy interesante. Enseña tecnologías actuales y se preocupa para que uno entienda lo que está haciendo. Los quices sirven para hacer los proyectos. Busque un buen equipo de trabajo.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Muchos proyectos grupales']::TEXT[], '2023-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'eb34143f702af933217110949f6bc139cae65ccdbbc707706017e48a85e8b535'::TEXT, ARRAY[1043]::BIGINT[]),
    (317::BIGINT, 'Para el curso de Bases 2 con este profe necesitará ser bastante ágil con estadística para poder tan solo plantear su proyecto final. Sino estará en manos de sus compañeros. Si nadie sabe, el gran proyecto final estará perdido desde el primer entregable.'::TEXT, 2.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Inspirador']::TEXT[], '2023-06-23T00:00:00+00:00'::TIMESTAMPTZ, '55b5415bb4df36bbd91a563ea40edb3c59d98d8f9e92ee7f37887b4363d4deb9'::TEXT, ARRAY[1043]::BIGINT[]),
    (317::BIGINT, 'Especificaciones confusas, trabajos largos y califica muy duro, hagale muchas preguntas para que tenga todo claro, eso si hagaselas con tiempo porque sino no contesta. Deja muchos quices pero la mayoria son realizables. Por ultimo, tenga una buena pareja de trabajo.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'ac1bad5de31e76a24fb46b1106876d45c72e005d3ea4437c1600a4101973a52b'::TEXT, ARRAY[1037]::BIGINT[]),
    (317::BIGINT, 'Un profe realmente bueno, siempre da un paso mas que el resto de profesores enseñando materia mas avanzada que se usa en el mundo laboal. Deja trabajos largos y complejos, pero es la unica manera de aprender. Matricularia con el de nuevo. Si quiere aprenedr mas que el resto y retarse llevelo con el.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Deja trabajos largos']::TEXT[], '2023-03-04T00:00:00+00:00'::TIMESTAMPTZ, '295af302d0ee37f1e0fa2658ac58bef85f5e31093b56196df33de249c8182e10'::TEXT, ARRAY[1029]::BIGINT[]),
    (317::BIGINT, 'Hágase un favor y no matrícule con ese profe que lo que está haciendo aquí al igual que el 65% de los profesores de computación es robarse el sueldo'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('30','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2022-11-29T00:00:00+00:00'::TIMESTAMPTZ, '0446658833ec815fad804443199d533e7c1648995ded5d39cdfda61bb72bed22'::TEXT, ARRAY[1029]::BIGINT[]),
    (317::BIGINT, 'Lo simplifico con una palabra... NO!'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2022-11-20T00:00:00+00:00'::TIMESTAMPTZ, 'a877f46d9767d6728ae7fdb024f39f60c4529bad41cf81a658224a78c5b035fb'::TEXT, ARRAY[1030, 1029]::BIGINT[]),
    (317::BIGINT, 'Nunca volvería a llevar con este profesor y no lo recomiendo en ningún aspecto, además de que califica extremadamente duro, también es irrespetuoso con sus estudiantes. Aunque hayas hecho todo bien y haciendo todo lo que enseñó en clase, si no lo haces igual como él lo hubiera hecho te baja todo.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos']::TEXT[], '2022-11-16T00:00:00+00:00'::TIMESTAMPTZ, '3ca88f4e043b4f08210bd529502fb272b0cae5cea3e583fe45847adf6a801bea'::TEXT, ARRAY[1030]::BIGINT[]),
    (317::BIGINT, 'De los peores profesores que he tenido en la carrera, mejor atrasarse un poco que tener que llevar un curso con este profesor'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2022-06-02T00:00:00+00:00'::TIMESTAMPTZ, '30ee2f5f1d8d688be1853376acfc87352535db0b7dcb6c0ba3b38867b0ed0389'::TEXT, ARRAY[1035]::BIGINT[]),
    (317::BIGINT, 'Es muy prepotente, como lo comentaron anteriormente. Califica demasiado duro, te baja muchos puntos por cosas pequeñas. Si se enoja por algo te habla feo, y al final dice "No se lo tomen personal". Se vuelve un curso demasiado pesado.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2022-05-12T00:00:00+00:00'::TIMESTAMPTZ, 'b36ea438418e3fd4add9d31debfa00975c245fa77acc0badd8bbab1f79c3bcbc'::TEXT, ARRAY[1035]::BIGINT[]),
    (317::BIGINT, 'Quiérase y respétese; no matricule NADA con él. Es un charlatán, deja quices confusos, sólo quiere atención y que le pregunten por todo, y si hace algo que no le gusta tiene cero. Aunque sea su única opción, lleve el curso después, y no deje que nadie matricule con él, es una pérdida de tiempo y paz'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2022-05-11T00:00:00+00:00'::TIMESTAMPTZ, '2a2bbfe51e305c4a6bbf053cea06afd99550f000a1ea437ebaf295536d13251a'::TEXT, ARRAY[1035]::BIGINT[]),
    (317::BIGINT, 'Siempre brinda apoyo con tecnología de punta, pero su curso tiene poco que ver con los temas de la carta al estudiante'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Deja trabajos largos']::TEXT[], '2022-04-09T00:00:00+00:00'::TIMESTAMPTZ, 'feb1f8d933d8eeeb316c604457b3dbdc24d506c0a830d347c78aafb96e5e76bd'::TEXT, ARRAY[1035]::BIGINT[]),
    (317::BIGINT, 'Muy mal profesor, no da retroalimentación, se abusa con su lenguaje, no sabe dar clases no lo recomiendo para nada'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clase fácil', 'Muchas tareas']::TEXT[], '2022-03-02T00:00:00+00:00'::TIMESTAMPTZ, '6976833a2b555e9595796e901ce073ada3b5eb495cb23a4e822c5a64acf1a98f'::TEXT, ARRAY[1035]::BIGINT[]),
    (317::BIGINT, 'El profe es pura vida con uno, sabe bastante y con solo leer el código sabe dónde están los problemas, no explica muy bien, pero es cuestión de agarrarle el toque. Las progras son bastante voladas pero posibles, eso sí, procure entender todo y preguntar, el profe es muy flexible con reuniones extra'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Deja trabajos largos']::TEXT[], '2022-01-21T00:00:00+00:00'::TIMESTAMPTZ, '5a0b338c72eb2966613ef60da35cb310ed08381a356287a5c13eac28700295da'::TEXT, ARRAY[1029]::BIGINT[]),
    (317::BIGINT, 'El curso que da es excelente, se aprende un montón, pero como profesor es otra historia, ud necesita estar encima de él preguntando porque sino los más seguro es que entregue las cosas mal (es difícil entender lo que quiere), es un poco propotente, deja bastantes casos y quices, 2 proyectos.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2022-01-21T00:00:00+00:00'::TIMESTAMPTZ, 'cacc5349fc68f45eda0297f9bf75d89660802116f24b7b6cc888b3785d71577e'::TEXT, ARRAY[1043]::BIGINT[]),
    (317::BIGINT, 'Es un buen profe, es necesario estar encima de él y preguntarle constantemente sobre los proyectos y tareas, con hacer eso, se pasa bien. Hay que ponerme muchas ganas al curso, pero el profe explica muy bien todo y se aprende mucho. Eso si, es un curso pesado.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-21T00:00:00+00:00'::TIMESTAMPTZ, '745a9cf3ec45881f2c38822cb79667d6d6377daad4b131afaf82063ef5c51148'::TEXT, ARRAY[1035]::BIGINT[]),
    (317::BIGINT, 'Te ayuda si estás encima de él, sin embargo las cosas deben ser a su manera o convencerlo de que es una muy buena manera, clases muy largas y aburridas'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, '9d49aed3d1bba40937509acaaf6adb770005d3cd09d97b9a98f8ef2883218ab2'::TEXT, ARRAY[1035]::BIGINT[]),
    (317::BIGINT, 'El profe es muy tuanis en general, sé ve que sabe demaciado y lo refleja en sus clases, es increible el nivel de ayuda que brinda, él le va a ayudar siempre y cuando usted se lo pida, el mae pasa el número y uno le manda mensajes por whatsapp.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Brinda apoyo']::TEXT[], '2021-07-09T00:00:00+00:00'::TIMESTAMPTZ, '21dcc1660dd65bba1cb9c8030d0a96a0e67bc7ff1d861343c9cf6933dda05847'::TEXT, ARRAY[1035]::BIGINT[]),
    (317::BIGINT, 'El peor profesor que he tenido en mi vida, intimida a los estudiantes, los maltrata cuando preguntan algo, pide algo en la tarea y luego en clase dice que de hecho quería otra cosa, y hace ejemplos super simples y en las progras pide algo 200 veces más difícil. Fue horrible.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-03T00:00:00+00:00'::TIMESTAMPTZ, '04cf131fb20de6085ae1f9c76eab89023756d19304c4e02e27a48f5d4340d877'::TEXT, ARRAY[1037]::BIGINT[]),
    (317::BIGINT, 'No entiendo como hay comentarios positivos de este profesor... No le interesa dar clases incluso las dio una vez en un restaurante, un irrespetuoso hasta más no poder, con las personas y con el tiempo de las mismas. El curso se pasa, pero definitivamente es un asco de profesor y de persona.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-03T00:00:00+00:00'::TIMESTAMPTZ, '0b5338269998d480499c0903342a76142739b5be84a9c5a9dd46453a1738fd27'::TEXT, ARRAY[1037]::BIGINT[]),
    (317::BIGINT, 'Uno de los peores profesores que he tenido, es un irrespetuoso. Dice que siempre está dispuesto a aclarar dudas de la mejor manera, pero eso solo lo hace con los estudiantes que tiene como favoritos. Se nota que solo es profesor para intentar ligarse a los estudiantes.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2021-07-01T00:00:00+00:00'::TIMESTAMPTZ, '6be28987631998ebc32d45e23f0bc005dd20b7bf7c1dcaf161953bb562fcc7cb'::TEXT, ARRAY[1035]::BIGINT[]),
    (317::BIGINT, 'La gente que dice "es super difícil pero muy bueno" que concepto tienen de buen profesor? El mae es una mierda, andarle detrás para que le explique cosas extra porque sino el proyecto no sale no es ser "bueno", se nota que no tiene balanza entre créditos y el trabajo que deja'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2021-06-14T00:00:00+00:00'::TIMESTAMPTZ, '14e174450c43d3cfd7ac5c83fdd5e96fa9719080e224d6d4b761c89be3578ce2'::TEXT, ARRAY[1035]::BIGINT[]),
    (317::BIGINT, 'Un buen profe la verdad, se aprende bastante!'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura']::TEXT[], '2021-01-26T00:00:00+00:00'::TIMESTAMPTZ, 'ad829f274253af2b5f4a83fb26586a0538f6877b9b5a7ee745f6ace43275a281'::TEXT, ARRAY[1035]::BIGINT[]),
    (317::BIGINT, 'El curso es díficil, pero se aprende mucho y es fundamental para la carrera. Los proyectos son complicados pero de estos se aprenden mucho. Es fundamental tener una buena comunicacion con él para pedir retroalimentacion de las soluciones del proyecto. Siempre está atento a contestar dudas.'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Deja trabajos largos']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, 'e6e335b5ebe3cd6f25a6c6c643a196acdfdd7ed9d97682f0d4dedcac29ad3bda'::TEXT, ARRAY[1035]::BIGINT[]),
    (317::BIGINT, 'Buen curso, sin duda el aprendizaje esta asegurado. Es bueno mantener comunicacion para que aprueben tus soluciones antes de ir directo a programar. Brinda ayuda a quien le pida y tiene buena experiencia, aveces llega tarde. Deja bastantes trabajos pero son realizables'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Deja trabajos largos', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, 'e462fa637efc5189c4f7c6d1d9c58712ca576740bb14ec0b5e33a3593af11a61'::TEXT, ARRAY[1035]::BIGINT[]),
    (317::BIGINT, 'Dejó un proyecto que vale 35%, está bastante complicado y se pusó a probar ideas con ese porcentaje... Cuando uno le pide ayuda casi que le tiene que rogar para sacarle algo, él cree que uno es un experto después de una explicación mediocre, y la primera mitad del curso es Bases I, otra vez...'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clase fácil', 'Muchos proyectos grupales']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, '97a4de28602a1e01d6224023d12fe53afd9ff50fca328c7e66982a13195a97fc'::TEXT, ARRAY[1043]::BIGINT[]),
    (317::BIGINT, 'Uno aprende, pero a huevo. Hace un curso de 3 créditos sentirse como de 4 o más. Las progras son voladas y sacadas del *. El mae no ha trabajado con las herramientas que lo pone a usar por lo que no espere ayuda en esos aspectos. Si quiere pasar, definitivamente con él no.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clase fácil', 'La participación importa']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, 'dfefd0524f92036eb8ed2dc7aa72780faf29145a7e087f696939635f9fb9b2d1'::TEXT, ARRAY[1043]::BIGINT[]),
    (317::BIGINT, 'Explica muy bien. Las progras son todo un reto de los cuales con suficiente dedicación y siempre consultado, se puede aprender demasiado. Pero si usted erra la idea o algo similar, preparse para perder una gran parte de la nota. Lo recomiendo para quien desee aprender más que solo pasar el curso.'::TEXT, 2.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Da crédito extra']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, '71bbd470a7a525e0b1db7dcb83bf59111dbccd74e4ea9dd0816f9d48e3db699e'::TEXT, ARRAY[1035]::BIGINT[]),
    (317::BIGINT, 'Proyectos muy grandes y complicados y usted tiene que caerle bien y tener la solución que él pensó, de lo contrario le va a poner peros a todo lo que usted hizo, no da la mitad de las clases por cosas como que se va a mudar de casa y las que da no las planea, pésimo profe no matricule con él'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2020-08-08T00:00:00+00:00'::TIMESTAMPTZ, '24d9a60620dbcccf1b0dd5ce231a8296284095b97158ca8e6c6f5131678b437d'::TEXT, ARRAY[1035]::BIGINT[]),
    (317::BIGINT, 'Mal organizado, no planea las clases y se nota mucho. Para pasar las progras hay que estar yendo a consulta porque uno no tiene la claridad de saber cómo es que él quiere las cosas. Aunque igual se nota que intenta adaptar lo que él quiere a más o menos lo que uno tiene'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Muy cómico']::TEXT[], '2020-07-30T00:00:00+00:00'::TIMESTAMPTZ, '89d276f0ae7df859246da08d09d2866e8af791e9a8e1a6e9a4c8b80fa3970d20'::TEXT, ARRAY[1035]::BIGINT[]),
    (317::BIGINT, 'Trate de no llevar con el, califica dependiendo como le caiga, la verdad que lo que explica solo se lo entiende un 30%. Muchos trabajos, puntos extra que lo pueden salvar. Si es mujer no lleve con el, mágicamente nunca le pasan.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2020-03-25T00:00:00+00:00'::TIMESTAMPTZ, '4d42bc6400a1ca8e1213df318c7965aeff347803fe6eb171165b7e7387def1bd'::TEXT, ARRAY[1035]::BIGINT[]),
    (317::BIGINT, 'Lo único bueno que tiene es que si uno va a consulta él ayuda. Añade muchas cosas extra que complican el curso mismo. Casi todo lo trabaja en Java, casi no se usa C++ como debería de ser. Mi recomendación es que si nunca ha llevado este curso busque otro profesor. No llevaría otro curso con él.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2020-02-28T00:00:00+00:00'::TIMESTAMPTZ, '36252021c667188582e43e8122bf94c41bd3799e68ca51ab1021d2516be51db3'::TEXT, ARRAY[1029]::BIGINT[]),
    (317::BIGINT, 'Clases confusas y desordenadas, poco claro. Es importante caerle bien. Si puede matricular con otro profe, hágalo.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Deja trabajos largos']::TEXT[], '2019-09-10T00:00:00+00:00'::TIMESTAMPTZ, '933b1d462e8b64862e2cd09c7fbd6a1901a69dfd8af6a4c76c71a91efe77217c'::TEXT, ARRAY[1029]::BIGINT[]),
    (317::BIGINT, 'Excelentes cursos los de Nuñez. Vale decir que en media clase no se aprende bastante de la materia del curso, pero de la experiencia de él y de los proyectos se aprende demasiado. Preguntándole, recibiendo retroalimentación y escuchando se le puede sacar mucho provecho, más allá de sólo el curso.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, '49c7b3e261c082a86a537207426ec31f1d4906622056809baf87922785c20fe3'::TEXT, ARRAY[1043]::BIGINT[]),
    (317::BIGINT, 'Canceló 50% de clases y al resto llegó tarde. Explica todo leyendo de un folleto y a veces no se entiede. Dejó de tarea un programa, lo entregamos, y luego decidió que esa era la tarea corta y en palabras de él "el que lo hizo charral salado", adiós 15% de la nota. Progras difíciles y poco claras.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación']::TEXT[], '2019-05-09T00:00:00+00:00'::TIMESTAMPTZ, '7564e426c675a945f8f7d712b3e4692cec2c0c7749237c3cf49bd3f324e667e6'::TEXT, ARRAY[1035]::BIGINT[]),
    (317::BIGINT, 'El problema es no prepararse bien para los proyectos porque valen casi todo el curso. Si uno muestra interés en la clase y pide asesoría en los proyectos el profe le da seguimiento a su trabajo, así se pasa el curso con él, pero si hay que ponerle. Se aprende mucho.'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Tomaría su clase nuevamente']::TEXT[], '2019-02-25T00:00:00+00:00'::TIMESTAMPTZ, 'd1abdb5f99ff6d2ce90c58cf5f2ddd5cb8f179c24a8ff4eab0130eeadce8f617'::TEXT, ARRAY[1035]::BIGINT[]),
    (317::BIGINT, 'Quices normales, proyectos muy dificiles, califica a como quiere. El peor profesor, mejor lleve con otro o espere un semestre.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'f169a5e50d0291458f04aa68383024306bff55761f8c3987e92623f067e9d5fa'::TEXT, ARRAY[1043]::BIGINT[]),
    (317::BIGINT, 'Llega tarde, aveces ni llega y lo deja mamando, pero cuando llega, se nota el manejo del profe en el tema de innovacion, Design Thinking, al punto que es muy interesante. Se pone en practica todo lo visto en clase. Al final hace un Shark Tank con empresarios reales lo cual es super chuzo!'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-27T00:00:00+00:00'::TIMESTAMPTZ, '56e5daccb69250ffa9c11add7f5c41a5e31f48cabad1a1514a4483c6cad181a7'::TEXT, ARRAY[1116]::BIGINT[]),
    (317::BIGINT, 'Es un profe excelente para explicar y para ayudarte, pero cuando te califica se pone duro. Hazle mucha consulta y pon atencion en las clases y te irá bien.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'La participación importa']::TEXT[], '2018-02-14T00:00:00+00:00'::TIMESTAMPTZ, 'f0e99aaa066923bcc945658ce8fda78b85dc0d181b627cd2481f735786c3812e'::TEXT, ARRAY[1029]::BIGINT[]),
    (317::BIGINT, 'Es el peor profesor que he tenido en el TEC, no hay claridad en lo trabajos que él quiere, revisa súper mal puede ser el mismo trabajo que si la persona le cae bien se lo califica mejor. Deja todo para el final, si pueden metan con alguien más'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2018-01-24T00:00:00+00:00'::TIMESTAMPTZ, 'a0f78b2077a74a983decf237b7ec7c6bd019b74a4dc5b500e292986104f4ab87'::TEXT, ARRAY[1043]::BIGINT[]),
    (317::BIGINT, 'Contesta preguntas por WS, hay proyectos muy volados (sobretodo el de big data), tiene que tener una buena compu (8 GB) si no quiere pasar en TM toda la semana. Se pasa más tiempo buscando como instalar cosas y aprendiendo la tecnología que programando. Súmele 2 créditos si lo va a llevar con él.'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchos proyectos grupales']::TEXT[], '2017-12-10T00:00:00+00:00'::TIMESTAMPTZ, '4eaaf9a2ce79bcadff6b69114d4120b3b8f1cdf340df2aa512d8dba5064551ae'::TEXT, ARRAY[1043]::BIGINT[]),
    (317::BIGINT, 'Actualizado. Califica muy duro. El curso con él es para sufrir. Quices aceptables.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Pocos exámenes', 'Deja trabajos largos']::TEXT[], '2017-12-03T00:00:00+00:00'::TIMESTAMPTZ, '19d5a1d31ad310e34fac0921aed55c8749785760e08eed423d967bc693ca6850'::TEXT, ARRAY[1043]::BIGINT[]),
    (317::BIGINT, 'Si le cae bien pasa sobrado si no prepárese para sufrir'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-02-01T00:00:00+00:00'::TIMESTAMPTZ, '3e5af9f30ad84151beba29718334154479c92f86342b4cd8792b7ffd6b3944a0'::TEXT, ARRAY[1043, 1037]::BIGINT[]),
    (317::BIGINT, 'Profesor rudo tanto en evaluaciones como proyectos. Actualizado con las tecnologías que se utilizan actualmente en el mercado, por lo que al saber enseñar se aprende demasiado. No deja exámenes pero los proyectos consumen demasiado tiempo y esfuerzo. Recomendado para cualquier curso.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Deja trabajos largos']::TEXT[], '2016-06-23T00:00:00+00:00'::TIMESTAMPTZ, '04216ca1eb1cd41060c1d57c39d1a6c0284a07eb5962cfb0da9d0869cd84e8c5'::TEXT, ARRAY[1043]::BIGINT[]),
    (317::BIGINT, 'Excelente profesor. Sin duda lo recomiendo porque está actualizado con lo que hay en el mercado. No es cierto lo de las preferencias, él es justo y si por un punto se queda, él no ayuda.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-22T00:00:00+00:00'::TIMESTAMPTZ, '83d2abc686d40fc248ac1fcfc37fe59e9afc340ce43ab4e78bf2d5c5bcce1e3a'::TEXT, ARRAY[1043]::BIGINT[]),
    (317::BIGINT, 'Muy buen profesor, aclara la mayoría de las dudas, los conocimientos que transmite son muy útiles y actualizados. Si le pone interés puede aprender bastante.El curso va a requerir que le dedique buen tiempo a los proyectos.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-22T00:00:00+00:00'::TIMESTAMPTZ, '890b4eb4702e9b578c199b66509836a8736f7cc08d17fca2c2cf4b72f11992a0'::TEXT, ARRAY[1043]::BIGINT[]),
    (317::BIGINT, 'Excelente profesor. Siempre trata de mantener a los estudiantes al hilo con lo que se usa en la calle mediante los proyectos. Exige mucho pero también aporta mucho. Super recomendado.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Deja trabajos largos', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-01T00:00:00+00:00'::TIMESTAMPTZ, 'b05dabef79a9c9947aeedec8ae5a6ad12196ce207708d701854112b13ecd7a11'::TEXT, ARRAY[1043, 1037]::BIGINT[]),
    (317::BIGINT, 'Si le cae bien pasa como si nada si no prepárese para pasarla mal'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-07-03T00:00:00+00:00'::TIMESTAMPTZ, 'a60c2f308bc7fb9ce5fa95f2e9072f8cbddd145a59c57a682d31dd8cea9992dd'::TEXT, ARRAY[1043, 1037]::BIGINT[]),
    (317::BIGINT, 'Es muy buen profe, es rudo pero se aprende mucho.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-23T00:00:00+00:00'::TIMESTAMPTZ, '36fb7f569723d8adfb3ba5335d69d1f28329153ec888169670d0367f11f9c0c3'::TEXT, ARRAY[1043]::BIGINT[]),
    (317::BIGINT, 'El mae es muy tuanis como persona, exige bastante, pero ayuda si se le busca. Hay que ponerle. Es un poco desordenado, y poco puntual para los compromisos. Las revisiones son brutales.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-22T00:00:00+00:00'::TIMESTAMPTZ, '51c0fd665603210aa07b2b552be292df28067822f0c0a59c7652395bbbea85e7'::TEXT, ARRAY[1035]::BIGINT[]),
    (317::BIGINT, 'Ha sido uno de los cursos mas interesantes y actuales que he llevado, Lo recomiendo al 100%'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-02T00:00:00+00:00'::TIMESTAMPTZ, '85454fb8875a6d0f4653f3f681166329a6a6f8af5eac44c1dd39cbecdbdbe134'::TEXT, ARRAY[1039]::BIGINT[]),
    (317::BIGINT, 'Nuñez es un excelente profesor. Si bien no va a ser un curso fácil, se aprenden cosas demasiado útiles, actualizadas e interesantes. Muy recomendado!'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-26T00:00:00+00:00'::TIMESTAMPTZ, 'c396ac1c51f554ae8c2b27ba4030bc5163c6ff8bdd7cf19ee882479cfa716bf8'::TEXT, ARRAY[1035]::BIGINT[]),
    (317::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('30','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-11T00:00:00+00:00'::TIMESTAMPTZ, '8c6c8d93e2166412e53ec1432e9431b0ab744d7d0f3ffdddd891e19025ae1f73'::TEXT, ARRAY[1035]::BIGINT[]),
    (317::BIGINT, 'Muy bueno explicando. Trabajos bien tuanis. Uno aprende demasiado. El mejor profesor de Bases De Datos. Si no está dando ese semestre, yo siendo ustedes me espero a que lo dé. Vale demasiado la pena.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-21T00:00:00+00:00'::TIMESTAMPTZ, 'e3bb551530bcb4452f94b32027e393715d330131622ccc6b018d81e887f11f1b'::TEXT, ARRAY[1037]::BIGINT[]),
    (317::BIGINT, 'Excelente profe pero muy rudo. un tapiz total'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-01T00:00:00+00:00'::TIMESTAMPTZ, '4af9ee6901cdc5890ef3d430cd6581bb262fe49bd90d57ab5ff29ff8d98fdeb5'::TEXT, ARRAY[1037]::BIGINT[]),
    (317::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-19T00:00:00+00:00'::TIMESTAMPTZ, 'd039eaff5eb8dacab3112c82253a4689ce8ba8f4ecc1b4b636f89951524fedb6'::TEXT, ARRAY[1035]::BIGINT[]),
